WITH Base AS (SELECT * FROM web_events WHERE event_time < '2024-08-18' AND (page = '/cart' OR duration_sec >= 348)), web_events_stats AS (SELECT CASE WHEN duration_sec >= 361 THEN 'high' WHEN duration_sec >= 210 THEN 'mid' ELSE 'low' END AS duration_sec_bucket, page, AVG(duration_sec) AS avg_duration_sec FROM Base GROUP BY CASE WHEN duration_sec >= 361 THEN 'high' WHEN duration_sec >= 210 THEN 'mid' ELSE 'low' END, page) SELECT duration_sec_bucket, page, avg_duration_sec FROM web_events_stats WHERE avg_duration_sec >= 240;
